package io.fireflysoftware.core.product.core.services.definition;

import static org.junit.jupiter.api.Assertions.*;
import io.fireflysoftware.core.product.core.services.definition.impl.*;
import io.fireflysoftware.core.product.interfaces.dtos.definition.*;
import io.fireflysoftware.core.product.interfaces.dtos.definition.ProductDefinitionLifecycleMessages.Parsed;
import io.fireflysoftware.core.product.models.repositories.definition.lifecycle.ProductDefinitionCommandPersistence;
import io.r2dbc.pool.*;
import java.lang.reflect.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.LongSupplier;
import org.fireflyframework.security.api.domain.Decision;
import org.junit.jupiter.api.Test;
import org.springframework.context.support.GenericApplicationContext;
import org.springframework.data.r2dbc.core.DefaultReactiveDataAccessStrategy;
import org.springframework.data.r2dbc.dialect.PostgresDialect;
import org.springframework.web.server.ResponseStatusException;
import reactor.core.publisher.Mono;

/** Controlled denied authority and real mapped factory; no business/native success facade. */
class TermPcEngineBindingTest {
    final TermPcLifecycleProfileTest source=new TermPcLifecycleProfileTest();
    ProductDefinitionLifecycleServiceImpl engine(ProductDefinitionCommandAuthorization auth,ProductDefinitionCommandPersistence p,GovernedDefinitionProfile backend){try{return ProductDefinitionLifecycleServiceImpl.class.getConstructor(ProductDefinitionCommandAuthorization.class,ProductDefinitionCommandPersistence.class,GovernedDefinitionProfile.class,Clock.class,LongSupplier.class).newInstance(auth,p,backend,Clock.fixed(TermPcLifecycleProfileTest.NOW,ZoneOffset.UTC),(LongSupplier)()->0);}catch(InvocationTargetException e){if(e.getCause()instanceof RuntimeException r)throw r;throw new AssertionError(e.getCause());}catch(ReflectiveOperationException e){throw new AssertionError("Fixed backend engine missing",e);}}
    ProductDefinitionCommandPersistence persistence(ConnectionPool pool,GenericApplicationContext c,boolean bounded){return new ProductDefinitionCommandPersistence(pool,new DefaultReactiveDataAccessStrategy(PostgresDialect.INSTANCE).getConverter(),c,bounded);}
    @Test void explicitTermPcEngineRejectsLegacyUnboundedPersistence(){var d=new InsuranceQuotePurposeTransactionTest.Driver();var pool=new ConnectionPool(ConnectionPoolConfiguration.builder(d).initialSize(0).build());try(var c=new GenericApplicationContext()){c.refresh();var auth=source.authority(GovernedDefinitionProfile.TERM_PC_INSURANCE.policyProfile(),GovernedDefinitionProfile.TERM_PC_INSURANCE,(p,a,r,x)->Mono.just(Decision.deny("DENIED")));assertThrows(IllegalArgumentException.class,()->engine(auth,persistence(pool,c,false),GovernedDefinitionProfile.TERM_PC_INSURANCE));assertEquals(0,d.creates);}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}
    @Test void engineAndAuthorityMustHaveSameBackendBinding(){var d=new InsuranceQuotePurposeTransactionTest.Driver();var pool=new ConnectionPool(ConnectionPoolConfiguration.builder(d).initialSize(0).build());try(var c=new GenericApplicationContext()){c.refresh();var auth=source.authority(ProductDefinitionCommandAuthorization.POLICY_PROFILE,GovernedDefinitionProfile.ACCOUNT_TARIFF,(p,a,r,x)->Mono.just(Decision.deny("DENIED")));assertThrows(IllegalArgumentException.class,()->engine(auth,persistence(pool,c,true),GovernedDefinitionProfile.TERM_PC_INSURANCE));assertEquals(0,d.creates);}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}
    @Test void validTermPcInputReachesCurrentDenialWithoutAnyDatabaseAcquisition(){var calls=new AtomicInteger();var d=new InsuranceQuotePurposeTransactionTest.Driver();var pool=new ConnectionPool(ConnectionPoolConfiguration.builder(d).initialSize(0).build());try(var c=new GenericApplicationContext()){c.refresh();var auth=source.authority(GovernedDefinitionProfile.TERM_PC_INSURANCE.policyProfile(),GovernedDefinitionProfile.TERM_PC_INSURANCE,(p,a,r,x)->{calls.incrementAndGet();assertEquals("INSURANCE",x.get("businessArea"));return Mono.just(Decision.deny("DENIED"));});var service=engine(auth,persistence(pool,c,true),GovernedDefinitionProfile.TERM_PC_INSURANCE);var e=assertThrows(ResponseStatusException.class,()->service.execute(TermPcLifecycleProfileTest.TENANT,TermPcLifecycleProfileTest.ROOT,ProductDefinitionCommand.CREATE_DRAFT,source.body(ProductDefinitionCommand.CREATE_DRAFT,"insurance").toString()).block());assertEquals(403,e.getStatusCode().value());assertEquals(1,calls.get());assertEquals(0,d.creates);}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}
    @Test void bankingInputCannotReachTermPcPdpOrAcquireDatabase(){var calls=new AtomicInteger();var d=new InsuranceQuotePurposeTransactionTest.Driver();var pool=new ConnectionPool(ConnectionPoolConfiguration.builder(d).initialSize(0).build());try(var c=new GenericApplicationContext()){c.refresh();var auth=source.authority(GovernedDefinitionProfile.TERM_PC_INSURANCE.policyProfile(),GovernedDefinitionProfile.TERM_PC_INSURANCE,(p,a,r,x)->{calls.incrementAndGet();return Mono.just(Decision.deny("DENIED"));});var service=engine(auth,persistence(pool,c,true),GovernedDefinitionProfile.TERM_PC_INSURANCE);var e=assertThrows(ResponseStatusException.class,()->service.execute(TermPcLifecycleProfileTest.TENANT,TermPcLifecycleProfileTest.ROOT,ProductDefinitionCommand.CREATE_DRAFT,source.body(ProductDefinitionCommand.CREATE_DRAFT,"account").toString()).block());assertEquals(400,e.getStatusCode().value());assertEquals(0,calls.get());assertEquals(0,d.creates);}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}
    @Test void allEightTermPcPlansRequireExplicitBackendAndRetainOriginalBytes(){for(var command:ProductDefinitionCommand.values()){var parsed=source.parse(command,source.body(command,"insurance").toString(),GovernedDefinitionProfile.TERM_PC_INSURANCE);try{var ids=Class.forName("io.fireflysoftware.core.product.core.services.definition.impl.ProductDefinitionCommandResources");var fresh=ids.getDeclaredMethod("fresh",ProductDefinitionCommand.class);fresh.setAccessible(true);var resources=fresh.invoke(null,command);var plan=Class.forName("io.fireflysoftware.core.product.core.services.definition.impl.ProductDefinitionCommandPlan");var encode=plan.getDeclaredMethod("encode",Parsed.class,ids,GovernedDefinitionProfile.class);encode.setAccessible(true);String text=(String)encode.invoke(null,parsed,resources,GovernedDefinitionProfile.TERM_PC_INSURANCE);assertEquals(parsed.intentDigest(),DefinitionCanonical.parse(text).get("originalIntentDigest").asText());assertEquals("TRUSTED_SERVICE",DefinitionCanonical.parse(text).get("validationBoundary").asText());}catch(InvocationTargetException e){throw new AssertionError(e.getCause());}catch(ReflectiveOperationException e){throw new AssertionError("Backend-bound native plan encoding missing",e);}}}
}
